/**
 * build-category-searches.js  —  n8n Code node
 * ------------------------------------------------------------------
 * Generates one item per category × search-query variation so the
 * downstream HTTP node hits ScrapingBee for each.
 *
 * Each item:
 *   { category, search_query, google_url }
 *
 * Categories: spa, restaurant, transport, tour, experience
 * 2 search variations per category = 10 total API calls per run.
 * ------------------------------------------------------------------
 */

const SEARCHES = [
  // --- SPA ---
  { category: 'spa', query: 'best luxury spa wellness Paris' },
  { category: 'spa', query: 'top-rated spa treatments hammam Paris 2026' },

  // --- RESTAURANT ---
  { category: 'restaurant', query: 'best restaurants Paris 2026 Michelin recommended' },
  { category: 'restaurant', query: 'top rooftop restaurants with Eiffel view Paris' },

  // --- TRANSPORT ---
  { category: 'transport', query: 'private chauffeur airport transfer Paris CDG Orly' },
  { category: 'transport', query: 'luxury car service with driver Paris' },

  // --- TOUR ---
  { category: 'tour', query: 'best private guided tours Paris museum Louvre Orsay' },
  { category: 'tour', query: 'Seine river cruise private boat Paris 2026' },

  // --- EXPERIENCE ---
  { category: 'experience', query: 'luxury exclusive experiences Paris private chef wine tasting' },
  { category: 'experience', query: 'unique romantic experiences Paris couples private tour' },
];

return SEARCHES.map(s => ({
  json: {
    category: s.category,
    search_query: s.query,
    google_url: 'https://www.google.com/search?q=' + encodeURIComponent(s.query),
    scraper_search_term: s.query,
  },
}));

/**
 * parse-scraped-services.js  —  n8n Code node
 * ------------------------------------------------------------------
 * Normalizes ScrapingBee extract_rules output into clean service records
 * ready for Airtable upsert.
 *
 * Input (per item):  { category, search_query, google_url } + scraper response
 * Output (0-N items): { name, category, phone, rating, reviews_count,
 *                        address, website, snippet, source, source_url }
 *
 * We extract structured data from Google organic results and drop anything
 * that doesn't look like a real business (no name, junk results, etc.).
 * ------------------------------------------------------------------
 */

const category = $json.category || 'other';
const source_query = $json.search_query || '';

// ---- 1. Unwrap the ScrapingBee response ---------------------------
function unwrap(resp) {
  if (!resp) return { results: [] };
  // ScrapingBee extract_rules returns { results: [...] }
  if (resp.results && Array.isArray(resp.results)) return resp;
  // Sometimes the HTTP node wraps in .data
  if (resp.data && resp.data.results) return resp.data;
  // Fallback: try to parse body
  if (typeof resp.body === 'string') {
    try { const parsed = JSON.parse(resp.body); if (parsed.results) return parsed; } catch {}
  }
  return { results: [] };
}

const raw = unwrap($json);

// ---- 2. Extraction helpers ----------------------------------------
const PHONE_RE = /(?:\+?\d[\d\s().-]{7,}\d)/;
const RATING_RE = /(\d(?:[.,]\d)?)\s*(?:\/\s*5|\bstars?\b|\bstars\b|★|\beval)/i;
const REVIEWS_RE = /(\d[\d.,]*)\s*(?:reviews?|avis|evaluations?)/i;
const ADDR_RE = /\b(?:\d{1,3}\s+)?(?:rue|avenue|boulevard|bd|av\.?|place|pl\.?|quai|faubourg|passage|cité|impasse|allée|cours|square)\s+[^,\n]{3,80}/i;

function cleanTitle(t) {
  if (!t) return '';
  // Remove Google suffix clutter: "— Restaurant à Paris", "| Site officiel", etc.
  return t.replace(/\s[–|\-|·|—]\s.*$/, '').replace(/\s{2,}/g, ' ').trim().slice(0, 150);
}

function firstMatch(re, s) {
  const m = (s || '').match(re);
  return m ? m[0].trim() : null;
}

function extractDomain(link) {
  if (!link) return null;
  try { return new URL(link).hostname.replace(/^www\./, ''); } catch { return null; }
}

// ---- 3. Build clean records ---------------------------------------
const seen = new Set();
const services = [];

for (const r of (raw.results || [])) {
  const title = cleanTitle(r.title);
  if (!title) continue;

  // Drop junk results (too short, map pins, Google ads labels)
  if (title.length < 3) continue;
  if (/^(map|maps|images|news|videos|shopping|books|flights|finance|maps\.google)/i.test(title)) continue;
  if (/^Ad\b|Sponsored|Annonce/i.test(title)) continue;

  const key = title.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  const text = `${title} ${r.snippet || ''}`;
  const rating_raw = firstMatch(RATING_RE, text);

  services.push({
    name: title,
    category: category,
    phone: firstMatch(PHONE_RE, text) || null,
    rating: rating_raw ? String(rating_raw).replace(',', '.') : null,
    reviews_count: firstMatch(REVIEWS_RE, text) || null,
    address: firstMatch(ADDR_RE, text) || 'Paris (exact address to be confirmed)',
    website: r.link || null,
    domain: extractDomain(r.link),
    snippet: (r.snippet || '').slice(0, 300),
    source: 'external',
    source_query: source_query,
    scraped_at: new Date().toISOString(),
  });

  // Cap at 5 results per search query (10 queries × 5 max = 50 total)
  if (services.length >= 5) break;
}

// ---- 4. Emit one item per service (or one empty item if none found)
if (services.length === 0) {
  return [{
    json: {
      _skip: true,
      category: category,
      found_count: 0,
      note: 'No usable results found for this query',
    },
  }];
}

return services.map(s => ({ json: s }));

/**
 * build-scrape-summary.js  —  n8n Code node
 * ------------------------------------------------------------------
 * Aggregates results across all categories and logs a summary.
 * Runs once after all upserts complete.
 *
 * Output: { total_upserted, categories_scraped[], services_by_category, ... }
 * ------------------------------------------------------------------
 */

const items = $input.all().map(item => item.json);

// Count by category
const byCategory = {};
for (const item of items) {
  if (item._skip) continue;
  const cat = item.category || 'other';
  byCategory[cat] = (byCategory[cat] || 0) + 1;
}

const totalUpserted = Object.values(byCategory).reduce((a, b) => a + b, 0);

const summaryLines = [
  `ConciergeFlow Scheduled Scrape — ${new Date().toISOString()}`,
  `Total services upserted: ${totalUpserted}`,
  ...Object.entries(byCategory).map(([cat, n]) => `  ${cat}: ${n} services`),
];

return [{
  json: {
    total_upserted: totalUpserted,
    categories_scraped: Object.keys(byCategory),
    services_by_category: byCategory,
    summary_text: summaryLines.join('\n'),
    timestamp: new Date().toISOString(),
  },
}];
